#define MM_FLOAT_PRECISION 998
#define MM_SIG_DIGITS      9     /* significant digits for PRINT         */
#define MM_FLOAT_DIGITS    6

void mm_int_to_str    (char *p, long long int nbr, int base);
void mm_int_to_str_pad(char *p, long long int nbr, signed char padch,
                       int maxch, int radix);
void mm_float_to_str  (char *p, MMFLOAT f, int m, int n, unsigned char ch);

/* ---- numeric helpers ----------------------------------------------- */
