MMINTEGER mm_idiv (MMINTEGER a, MMINTEGER b);   /*  \   */
MMINTEGER mm_mod  (MMINTEGER a, MMINTEGER b);   /* MOD  */
MMFLOAT   mm_pow  (MMFLOAT a, MMFLOAT b);       /*  ^   */
