char *mm_space (MMINTEGER n);
char *mm_strrep(MMINTEGER n, MMINTEGER c);          /* STRING$(n, c)   */
char *mm_str_f (MMFLOAT v,   MMINTEGER m, MMINTEGER n, const char *pad);
