void mm_set_time(const char *t);         /* TIME$ =                    */

/* ---- LONGSTRING ------------------------------------------------------
 * The firmware's convention (see misc/Custom.c): a long string lives in
 * an INTEGER array with the byte count in element 0 and the raw payload,
 * NOT NUL terminated, from element 1 onward.  So DIM b%(n) holds up to
 * n*8 bytes.  Every entry point here takes the array base and the total
 * element count, and refuses to run past the end - the manual calls an
 * overflow "undefined", so a clean error is a strict improvement.
 * ------------------------------------------------------------------- */
MMINTEGER mm_ls_len(const MMINTEGER *a);
void mm_ls_clear  (MMINTEGER *a, int cells);
void mm_ls_append (MMINTEGER *a, int cells, const char *s);
void mm_ls_load   (MMINTEGER *a, int cells, MMINTEGER n, const char *s);
void mm_ls_copy   (MMINTEGER *d, int dcells, const MMINTEGER *s);
void mm_ls_concat (MMINTEGER *d, int dcells, const MMINTEGER *s);
void mm_ls_left   (MMINTEGER *d, int dcells, const MMINTEGER *s, MMINTEGER n);
void mm_ls_right  (MMINTEGER *d, int dcells, const MMINTEGER *s, MMINTEGER n);
void mm_ls_mid    (MMINTEGER *d, int dcells, const MMINTEGER *s,
                   MMINTEGER start, MMINTEGER n);   /* n < 0 = to the end */
void mm_ls_replace(MMINTEGER *a, int cells, const char *s, MMINTEGER start);
void mm_ls_resize (MMINTEGER *a, int cells, MMINTEGER n);
void mm_ls_setbyte(MMINTEGER *a, int cells, MMINTEGER n, MMINTEGER v);
void mm_ls_trim   (MMINTEGER *a, int cells, MMINTEGER n);
void mm_ls_ucase  (MMINTEGER *a);
void mm_ls_lcase  (MMINTEGER *a);
void mm_ls_print  (MMINTEGER fnbr, const MMINTEGER *a, int nl);

char      *mm_ls_getstr (const MMINTEGER *a, MMINTEGER start, MMINTEGER len);
MMINTEGER  mm_ls_getbyte(const MMINTEGER *a, MMINTEGER n, int base);
MMINTEGER  mm_ls_instr  (const MMINTEGER *a, const char *pat, MMINTEGER start);
MMINTEGER  mm_ls_compare(const MMINTEGER *a, const MMINTEGER *b);
MMINTEGER  mm_ls_input  (MMINTEGER *a, int cells, MMINTEGER fnbr, MMINTEGER n);

/* ---- GOSUB / RETURN --------------------------------------------------
 * A GOSUB compiles to "push a site id, goto the label" and a RETURN to a
 * switch on the popped id that jumps back.  MMBasic allows 50 levels.  */
#ifndef MM_MAXGOSUB
#define MM_MAXGOSUB 50
#endif
void mm_gosub_push(int site);
int  mm_gosub_pop (void);

/* MID$(s, start, num) = repl$   (the statement form) */
void mm_mid_assign(char *dst, MMINTEGER start, MMINTEGER num, const char *repl);

/* ---- graphics (PC3) --------------------------------------------------
 * Colours are ALWAYS RGB888, as everywhere in MMBasic; the kernel
 * primitive converts to whatever the current mode uses (0/1 for the
 * 1bpp modes, nearest of the 16 logical colours for 4bpp).  Nothing
 * here knows about the mode.
 *
 * On the host these are no-ops returning black, so a translated
 * program that draws still runs under the gates.  */

/* Passed as the colour by a statement that was given none: draw in
 * whatever COLOUR last set.  Resolved inside the primitive so the hot
 * path stays one call, rather than the caller fetching it first. */
#define MM_CUR (-1)

/* MODE n: 1 = 640x480 one bit, 2 = 320x240 sixteen colours.  The
 * PicoMite VGA numbering, which is also the first two HDMI modes - NOT
 * the kernel's own, where 0-5 are the BBC modes and the 320x240 screen
 * is 7.  The mapping is in mm_mode. */
void mm_mode(MMINTEGER n);
/* COLOUR fg [, bg].  Pass MM_CUR as bg to leave the background alone.
 * The kernel holds one colour and knows nothing of a background; bg is
 * kept here for TEXT and filled shapes. */
void mm_colour(MMINTEGER fg, MMINTEGER bg);
MMINTEGER mm_fg(void);
MMINTEGER mm_bg(void);
void mm_cls(void);
void mm_pixel(MMINTEGER x, MMINTEGER y, MMINTEGER rgb);
MMINTEGER mm_pixel_get(MMINTEGER x, MMINTEGER y);
/* A line.  Axis-aligned ones become a single span in the kernel, which
 * is an order of magnitude cheaper than plotting them point by point. */
void mm_line(MMINTEGER x1, MMINTEGER y1, MMINTEGER x2, MMINTEGER y2,
             MMINTEGER rgb);
/* MM.HRES / MM.VRES - the drawable size, straight from the kernel, so
 * it follows a mode change without the program knowing anything. */
MMINTEGER mm_hres(void);
MMINTEGER mm_vres(void);
/* The two batched primitives everything in mmb_gfx.h is built from: a
 * run of points (two shorts each) and a run of rectangles (four), both
 * drawn in one colour.  The array is passed to the kernel as it stands
 * - that layout is what the batch ioctls already read - so a circle
 * crosses into the kernel a handful of times, not once per pixel. */
void mm_plot(const short *xy, MMINTEGER n, MMINTEGER rgb);
void mm_fill(const short *xyxy, MMINTEGER n, MMINTEGER rgb);
/* MMBasic's PIXEL x%(), y%(), c%().  Either the float or the integer
 * pointer of each pair is used, whichever the array actually is; pass
 * NULL for both colour pointers to draw in the current colour. */
void mm_pixels(const MMFLOAT *xf, const MMINTEGER *xi,
               const MMFLOAT *yf, const MMINTEGER *yi,
               const MMFLOAT *cf, const MMINTEGER *ci,
               MMINTEGER count);

/* ---- misc ----------------------------------------------------------- */
void mm_error(const char *msg);     /* prints and exits                */
void mm_end  (void);                /* the END statement               */
MMFLOAT mm_timer(void);             /* ms since TIMER=, with fraction  */

